#!/usr/bin/env node
import fs from'node:fs';import{spawnSync}from'node:child_process';
const OP='COMPASS_MIRRORLAND_CRYSTAL_ANIMATION_MODERNIZATION_PERFORMANCE_CONTINUATION_GEN1531',LOCK=1531,BASE='74de0882af55fed53272a191b173e45f5cdbd551',OUT=process.env.COMPASS_VERIFICATION_OUTPUT||'/tmp/compass-gen1531-display.json';const git=a=>spawnSync('git',a,{encoding:'utf8'}),read=p=>fs.readFileSync(p,'utf8'),checks=[],check=(id,pass,evidence)=>checks.push({id,pass:Boolean(pass),evidence});
const head=git(['rev-parse','HEAD^{commit}']).stdout.trim(),expected=(process.env.COMPASS_CANDIDATE_HEAD||head).trim();check('EXACT_HEAD',head===expected,{head,expected});check('BASE_ANCESTOR',git(['merge-base','--is-ancestor',BASE,head]).status===0,{BASE,head});
const html=read('index.html'),m=read('assets/compass/compass.mirrorland-window.js'),c=read('assets/compass/compass.crystals.js');check('FOUR_CARDINALS',(html.match(/data-cardinal-id="(north|east|south|west)"/g)||[]).length===4,'4');check('NINETEEN_ROOMS',(html.match(/data-compass-room data-compass-destination/g)||[]).length===19,'19');check('MIRRORLAND_ROUTES',['Enter the Narrative','Enter the Demo','See the World Map','Return to Compass'].every(x=>html.includes(x)),'routes');check('MIRRORLAND_STATE_MEANING',['MIRRORLAND_REVEALING','MIRRORLAND_FOCUSED','MIRRORLAND_WITHDRAWING','MIRRORLAND_WINDOW_REVEAL_COMPLETE','MIRRORLAND_WINDOW_WITHDRAWAL_COMPLETE'].every(x=>m.includes(x)),'state meaning preserved');check('MIRRORLAND_GEOMETRY_PRESENT',m.includes('function buildPanes()')&&m.includes('createPane(')&&m.includes('paneCount'),'stained-glass geometry retained');check('CRYSTAL_INTERACTION_PRESENT',c.includes('bindPointerBridge')&&c.includes('bindSemanticFocusBridge')&&c.includes('gestureActive'),'gesture/focus bridges retained');
for(const p of ['assets/compass/compass.identity-3d.js','assets/compass/compass.brain-scene.js','assets/compass/upstream-compass.renderer.js','assets/compass/compass.controller.js','assets/compass/compass.capability-carousel.js'])check(`BYTE_PRESERVED_${p.split('/').pop().replace(/\W/g,'_').toUpperCase()}`,git(['diff','--quiet',BASE,head,'--',p]).status===0,p);
const perf=spawnSync(process.execPath,['.github/ai-router/projects/compass/verify-performance-successor.mjs'],{encoding:'utf8',env:{...process.env,COMPASS_CANDIDATE_HEAD:head}});check('STATIC_PERFORMANCE_PASS',perf.status===0,{status:perf.status,stderr:perf.stderr.slice(-500)});const failures=checks.filter(x=>!x.pass),receipt={schema:'COMPASS_GEN1531_DISPLAY_CONTINUITY_RECEIPT_v1',operationId:OP,lockGeneration:LOCK,governingHead:BASE,candidateHead:head,result:failures.length?'FAIL_CLOSED':'PASS_CLOSED',checks,failures:failures.map(x=>x.id)};fs.writeFileSync(OUT,JSON.stringify(receipt,null,2)+'\n');console.log(JSON.stringify(receipt,null,2));if(failures.length)process.exit(1);
